"use client";
/* Pix, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Pix(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("pix"); }, []);
  return React.createElement("piix-pal", { "pal": "pix", ...piixAttrs(props) });
}

export default Pix;
